import React, { useEffect, useRef, useState } from 'react';
import { io } from 'socket.io-client';

const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000';

export default function ChatWidget() {
  const [open, setOpen] = useState(false);
  const [conversationId, setConversationId] = useState(Number(localStorage.getItem('conversationId')) || null);
  const [name, setName] = useState(localStorage.getItem('visitorName') || '');
  const [contact, setContact] = useState(localStorage.getItem('visitorContact') || '');
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState('');
  const socketRef = useRef(null);
  const messagesRef = useRef(null);

  useEffect(() => {
    const s = io(SOCKET_URL, { autoConnect: true });
    socketRef.current = s;

    s.on('connect', () => {
      // console.log('chat socket connected', s.id);
    });

    s.on('new_message', (msg) => {
      setMessages(prev => [...prev, msg]);
    });

    s.on('message_created', (msg) => {
      setMessages(prev => [...prev, msg]);
    });

    s.on('conversation_created', (conv) => {
      // nothing for now
    });

    return () => s.disconnect();
  }, []);

  useEffect(() => {
    if (conversationId && socketRef.current) {
      socketRef.current.emit('join_conversation', conversationId);
      fetch(`/api/conversations/${conversationId}/messages`)
        .then(r => {
          if (r.ok && r.headers.get('content-type')?.includes('application/json')) return r.json();
          throw new Error('Server error');
        })
        .then(setMessages)
        .catch(() => setMessages([]));
    }
  }, [conversationId]);

  useEffect(() => { if (messagesRef.current) messagesRef.current.scrollTop = messagesRef.current.scrollHeight; }, [messages]);

  const startConversation = () => {
    const guestName = name.trim() || 'زائر';
    const payload = { guestName, guestContact: contact };
    
    const handleSuccess = (conv) => {
        setConversationId(conv.id);
        localStorage.setItem('conversationId', conv.id);
        localStorage.setItem('visitorName', guestName);
        localStorage.setItem('visitorContact', contact);
        if (socketRef.current) socketRef.current.emit('join_conversation', conv.id);
        setOpen(true);
    };

    const performFetch = () => {
      fetch('/api/conversations', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
          .then(r => {
             if (r.ok && r.headers.get('content-type')?.includes('application/json')) return r.json();
             throw new Error('Server error');
          })
          .then(handleSuccess)
          .catch(() => alert('عذراً، الخادم غير متصل حالياً.'));
    };

    if (socketRef.current && socketRef.current.connected) {
      socketRef.current.emit('create_conversation', payload, (res) => {
        if (res && res.ok && res.conversation) {
          handleSuccess(res.conversation);
        } else {
          performFetch();
        }
      });
    } else {
      performFetch();
    }
  };

  const sendMessage = () => {
    if (!text || !conversationId) return;
    const payload = { conversationId, sender: 'visitor', senderName: name, text };
    socketRef.current.emit('send_message', payload, (res) => {
      if (res && res.ok && res.message) {
        setMessages(prev => [...prev, res.message]);
        setText('');
      } else {
        fetch('/api/messages', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
          .then(r => {
             if (r.ok && r.headers.get('content-type')?.includes('json')) return r.json();
             throw new Error('فشل الإرسال');
          })
          .then(m => { setMessages(prev => [...prev, m]); setText(''); })
          .catch(() => alert('لم يتم إرسال الرسالة، تأكد من الاتصال.'));
      }
    });
  };

  return (
    <div style={{ position: 'fixed', right: 20, bottom: 20, zIndex: 1050 }}>
      {!open ? (
        <div>
          <button className="btn btn-primary" onClick={() => setOpen(true)} style={{ minWidth: 56 }}>💬</button>
          <div style={{ width: 320, marginTop: 8 }}>
            <div className="card p-2">
              <div className="mb-2 small text-muted">تحدث معنا الآن</div>
              <input className="form-control form-control-sm mb-1" placeholder="الاسم (اختياري)" value={name} onChange={e => setName(e.target.value)} />
              <input className="form-control form-control-sm mb-1" placeholder="رقم الهاتف (اختياري)" value={contact} onChange={e => setContact(e.target.value)} />
              <div className="d-grid">
                <button className="btn btn-sm btn-success" onClick={startConversation}>بدء المحادثة</button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div style={{ width: 320 }} className="card">
          <div className="card-header d-flex justify-content-between align-items-center">
            <strong>دردشة الدعم</strong>
            <div>
              <button className="btn btn-sm btn-outline-secondary me-1" onClick={() => { setOpen(false); }}>إغلاق</button>
              <button className="btn btn-sm btn-outline-danger" onClick={() => { setConversationId(null); localStorage.removeItem('conversationId'); setMessages([]); setOpen(false); }}>إنهاء</button>
            </div>
          </div>
          <div ref={messagesRef} style={{ height: 260, overflowY: 'auto', padding: 8 }}>
            {messages.map((m, i) => (
              <div key={i} style={{ marginBottom: 8 }}>
                <div className="small text-muted">{m.sender === 'visitor' ? (m.senderName || 'أنت') : (m.senderName || 'المندوب')} • <small className="text-muted">{new Date(m.ts || m.ts).toLocaleString()}</small></div>
                <div style={{ background: m.sender === 'visitor' ? '#e9f7ef' : '#f1f1f1', padding: 8, borderRadius: 6 }}>{m.text}</div>
              </div>
            ))}
            {messages.length === 0 && <div className="small text-muted">لا توجد رسائل بعد</div>}
          </div>
          <div className="card-body">
            <div className="input-group">
              <input className="form-control form-control-sm" value={text} onChange={e => setText(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} placeholder="أكتب رسالة..." />
              <button className="btn btn-sm btn-primary" onClick={sendMessage}>إرسال</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
